// Vector Field — Distribution, route: jsx
// Source: vector-field
//
// Self-contained: every local import is inlined below. Requires only d3, react.
// Generated by scripts/build-exemplars.mjs — edit src/gallery/, not this file.

import { useMemo } from 'react';
import * as d3 from 'd3';

// ---- inlined from Axis ----
type Tick = { value: string; offset: number };

function AxisBottom({
  ticks,
  height,
  width
}: {
  ticks: Tick[];
  height: number;
  width: number;
}) {
  return (
    <g className="axis" transform={`translate(0,${height})`}>
      <line x1={0} x2={width} y1={0} y2={0} />
      {ticks.map(({ value, offset }) => (
        <g key={value} transform={`translate(${offset},0)`}>
          <line y1={0} y2={5} />
          <text y={18} textAnchor="middle">
            {value}
          </text>
        </g>
      ))}
    </g>
  );
}

function AxisLeft({ ticks, width }: { ticks: Tick[]; width: number }) {
  return (
    <g className="axis">
      {ticks.map(({ value, offset }) => (
        <g key={value} transform={`translate(0,${offset})`}>
          <line className="grid" x1={0} x2={width} y1={0} y2={0} />
          <text x={-10} dy="0.32em" textAnchor="end">
            {value}
          </text>
        </g>
      ))}
    </g>
  );
}

const MARGIN = { top: 46, right: 16, bottom: 36, left: 46 };
const X_DOMAIN: [number, number] = [0, 4 * Math.PI];
const Y_DOMAIN: [number, number] = [0, 2 * Math.PI];

// The notebook's arrow: a narrow triangle whose tip points down (+y) before rotation,
// so a uniform scale encodes speed and a rotation encodes direction.
const ARROW = 'M-2,-2L2,-2L0,8Z';
const ARROW_LENGTH = 10; // the path spans y from -2 to 8

/** Taylor-Green vortex: closed form, so the field needs no dataset. */
function taylorGreen(x: number, y: number): [number, number] {
  return [Math.sin(x) * Math.cos(y), -Math.cos(x) * Math.sin(y)];
}

type Arrow = { key: string; cx: number; cy: number; scale: number; rotate: number; hue: number };

const PI_TICKS: { at: number; label: string }[] = [
  { at: 0, label: '0' },
  { at: Math.PI, label: 'π' },
  { at: 2 * Math.PI, label: '2π' },
  { at: 3 * Math.PI, label: '3π' },
  { at: 4 * Math.PI, label: '4π' }
];

export default function VectorField({ width }: { width: number }) {
  const height = Math.round(width * 0.66);
  const innerWidth = width - MARGIN.left - MARGIN.right;
  const innerHeight = height - MARGIN.top - MARGIN.bottom;

  const x = useMemo(() => d3.scaleLinear(X_DOMAIN, [0, innerWidth]), [innerWidth]);
  const y = useMemo(() => d3.scaleLinear(Y_DOMAIN, [innerHeight, 0]), [innerHeight]);

  const arrows: Arrow[] = useMemo(() => {
    if (innerWidth <= 0 || innerHeight <= 0) return [];

    // Grid resolution follows pixel width, so 320px stays legible and full width stays sane.
    const columns = Math.max(8, Math.min(28, Math.round(innerWidth / 26)));
    const step = innerWidth / columns;
    const rows = Math.max(4, Math.round(innerHeight / step));

    const samples = d3.cross(d3.range(columns), d3.range(rows)).map(([i, j]) => {
      const cx = (i + 0.5) * step;
      const cy = (j + 0.5) * (innerHeight / rows);
      const [u, v] = taylorGreen(x.invert(cx), y.invert(cy));
      return { key: `${i}-${j}`, cx, cy, u, v, speed: Math.hypot(u, v) };
    });

    const length = d3
      .scaleSqrt([0, d3.max(samples, (s) => s.speed) ?? 1], [0, (step * 0.95) / ARROW_LENGTH]);

    return samples.map(({ key, cx, cy, u, v, speed }) => ({
      key,
      cx,
      cy,
      scale: length(speed),
      // Screen y is flipped, and the untransformed tip points at (0, 1).
      rotate: (Math.atan2(-u, -v) * 180) / Math.PI,
      hue: ((Math.atan2(v, u) * 180) / Math.PI + 360) % 360
    }));
  }, [innerWidth, innerHeight, x, y]);

  const color = useMemo(() => d3.scaleSequential([0, 360], d3.interpolateRainbow), []);

  const xTicks: Tick[] = useMemo(
    () => PI_TICKS.map((t) => ({ value: t.label, offset: x(t.at) })),
    [x]
  );

  const yTicks: Tick[] = useMemo(
    () =>
      PI_TICKS.filter((t) => t.at <= Y_DOMAIN[1]).map((t) => ({
        value: t.label,
        offset: y(t.at)
      })),
    [y]
  );

  if (width === 0) return null;

  const legendSteps = d3.range(0, 360, 10);
  const swatch = Math.min(innerWidth, 220) / legendSteps.length;

  return (
    <svg
      viewBox={`0 0 ${width} ${height}`}
      width="100%"
      height={height}
      role="img"
      aria-label="Vector field of the Taylor-Green vortex, u equals sine x cosine y and v equals minus cosine x sine y, drawn as a grid of arrows sized by speed and coloured by direction"
    >
      {/* Direction ramp: interpolateRainbow is cyclic, so 0 and 360 degrees share a hue. */}
      <g transform={`translate(${MARGIN.left},10)`}>
        <text y={-1} fill="var(--muted)" fontSize={11}>
          Direction
        </text>
        {legendSteps.map((deg, i) => (
          <rect
            key={deg}
            x={i * swatch}
            y={4}
            width={swatch + 0.5}
            height={10}
            fill={color(deg)}
          />
        ))}
        {[0, 90, 180, 270, 360].map((deg) => (
          <text
            key={deg}
            x={(deg / 10) * swatch}
            y={26}
            fill="var(--muted)"
            fontSize={10}
            textAnchor="middle"
          >
            {deg}°
          </text>
        ))}
      </g>

      {innerWidth > 420 && (
        <text
          x={width - MARGIN.right}
          y={20}
          fill="var(--muted)"
          fontSize={11}
          textAnchor="end"
        >
          Taylor-Green vortex: u = sin x cos y, v = −cos x sin y
        </text>
      )}

      <g transform={`translate(${MARGIN.left},${MARGIN.top})`}>
        <AxisLeft ticks={yTicks} width={innerWidth} />
        <g>
          {arrows.map((a) => (
            <path
              key={a.key}
              d={ARROW}
              transform={`translate(${a.cx},${a.cy}) rotate(${a.rotate}) scale(${a.scale})`}
              fill={color(a.hue)}
            />
          ))}
        </g>
        <AxisBottom ticks={xTicks} height={innerHeight} width={innerWidth} />
      </g>

      <text x={MARGIN.left} y={height - 3} fill="var(--muted)" fontSize={10}>
        Arrow length ∝ √speed
      </text>
    </svg>
  );
}
